# Decorators - dreams within dreams
import functools
import time
from typing import Callable, TypeVar, Any

# A simple timing decorator
def timer(func):
    @functools.wraps(func)  # Preserves metadata of the wrapped function
    def wrapper(*args, **kwargs):
        start_time = time.time()
        result = func(*args, **kwargs)
        end_time = time.time()
        print(f"{func.__name__} executed in {end_time - start_time:.4f} seconds")
        return result
    return wrapper

# A decorator factory that allows customization
def repeat(num_times):
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            results = []
            for _ in range(num_times):
                results.append(func(*args, **kwargs))
            return results
        return wrapper
    return decorator

# Generators - sustainable computation
def fibonacci():
    a, b = 0, 1
    while True:
        yield a
        a, b = b, a + b

# A generator that consumes another generator
def take(n, iterable):
    for i, item in enumerate(iterable):
        if i >= n:
            break
        yield item

# Metaclasses - this is not a class
class ValidationMeta(type):
    def __new__(mcs, name, bases, attrs):
        # Add validation to all methods that start with 'validate_'
        for attr_name, attr_value in attrs.items():
            if attr_name.startswith('validate_') and callable(attr_value):
                attrs[attr_name] = timer(attr_value)  # Apply decorator

        # Create a registry of all models if this is a Model subclass
        if name != 'Model' and bases and any(base.__name__ == 'Model' for base in bases):
            if not hasattr(mcs, 'registry'):
                mcs.registry = {}
            mcs.registry[name] = attrs

        return super().__new__(mcs, name, bases, attrs)

# A base class using our metaclass
class Model(metaclass=ValidationMeta):
    def __init__(self, **kwargs):
        for key, value in kwargs.items():
            setattr(self, key, value)

# Functional programming - mathematical harmony
def is_even(n):
    return n % 2 == 0

def square(n):
    return n * n

# Combining our patterns
@timer
@repeat(3)
def compute_sequence():
    """Generate the first 10 Fibonacci numbers, square them, and keep only even results."""
    fib_gen = fibonacci()
    fib_numbers = list(take(10, fib_gen))

    # Functional approach to transform the data
    squared = map(square, fib_numbers)
    even_squares = filter(is_even, squared)

    return list(even_squares)

# A model class that will be processed by our metaclass
class User(Model):
    def validate_email(self, email):
        # This method will automatically get the @timer decorator
        # from our metaclass
        if '@' not in email:
            raise ValueError("Invalid email format")
        return True

# Demonstrating our patterns
print("Advanced patterns in action:")
result = compute_sequence()
print(f"Result: {result}")

user = User(name="Alice", email="alice@example.com")
user.validate_email(user.email)
